(2312,"چکن نگٹس ہنی مسٹرڈ ڈِپنگ ساس کے ساتھ","ڈی واٹا (DaVita) کی غذائی ماہرین کی ٹیم کی طرف سے پیش کردہ ہنی مسٹرڈ ڈِپنگ ساس کے ساتھ چکن نگٹس کی یہ ترکیب نہ صرف لذیذ ہے بلکہ گردوں کے لیے موزوں بھی ہے۔ مختلف ڈِپنگ ساسز آزمائیں، جیسے: باربی کیو ساس، کری ساس، پھلوں کے اسپریڈ یا کم سوڈیم والی سلاد ڈریسنگ۔","12","3 نگٹس، اور 1 کھانے کا چمچ ساس",
["1 کھانے کا چمچ پیلی سرسوں","½ کپ مایونیز","⅓ کپ شہد","2 چائے کے چمچ ورسسٹرشائر ساس","1 بڑا انڈا","2 کھانے کے چمچ 1% کم چکنائی والا دودھ","3 کپ کارن فلیکس","1 پاؤنڈ ہڈی کے بغیر چکن بریسٹ"],
["ایک چھوٹے پیالے میں سرسوں، مایونیز، شہد اور ورسسٹرشائر ساس ملا لیں۔ ساس کو ٹھنڈا ہونے کے لیے فریج میں رکھ دیں جب تک نگٹس تیار نہ ہو جائیں، پھر ڈِپنگ ساس کے طور پر پیش کریں۔","اوون کو 400° F پر پہلے سے گرم کریں۔","چکن بریسٹ کو 36 نوالے کے سائز کے ٹکڑوں میں کاٹ لیں۔","کارن فلیکس کو کچل لیں اور چورا ایک بڑے زپ لاک تھیلے میں ڈال دیں۔","ایک چھوٹے پیالے میں پھینٹا ہوا انڈا اور دودھ ملا لیں۔ چکن کے ٹکڑوں کو انڈے کے مکسچر میں ڈبوئیں، پھر زپ لاک تھیلے میں ہلائیں تاکہ ان پر کارن فلیکس کا چورا لگ جائے۔","نگٹس کو نان اسٹک کوکنگ اسپرے لگی بیکنگ شیٹ پر 15 منٹ یا پکنے تک بیک کریں۔"],
["نگٹس کو سجائے ہوئے ٹوتھ پکس کے ساتھ ٹرے میں پیش کریں تاکہ تہوار جیسا انداز بنے۔","مختلف ڈِپنگ ساسز آزمائیں، جیسے: باربی کیو ساس، کری ساس، پھلوں کے اسپریڈ یا کم سوڈیم والی سلاد ڈریسنگ۔","تین ٹکڑے ایک اپیٹائزر کی مقدار ہے۔ مکمل کھانے کے لیے مقدار بڑھا کر 6 سے 9 نگٹس کر لیں۔","اگر دستیاب ہوں تو کم سوڈیم والے کارن فلیکس استعمال کریں تاکہ 3 ٹکڑوں کا سوڈیم کم ہو کر 116 ملی گرام رہ جائے۔"],
["1 گوشت","½ نشاستہ","½ زیادہ کیلوری","1 چکنائی"]),
(2314,"سالمن سلاد سینڈوچ فلنگ","جب آپ یہ مزیدار سالمن سلاد سینڈوچ فلنگ اپنی پسندیدہ گردوں کے لیے موزوں ڈبل روٹی یا کریکر پر لگاتے ہیں تو اومیگا-3 کی مقدار بڑھانا آسان ہو جاتا ہے۔","2","ترکیب کا ½",
["5 اونس ڈبہ بند سالمن","1 کھانے کا چمچ اجوائن (سیلری)","3 کھانے کے چمچ مایونیز","½ چائے کا چمچ لیموں کا رس","⅛ چائے کا چمچ کالی مرچ"],
["اجوائن کو باریک کاٹ لیں۔","ایک چھوٹے پیالے میں سالمن کو باقی اجزا کے ساتھ ملا لیں۔","سینڈوچ بنائیں یا کم سوڈیم والے کریکرز کے ساتھ کھائیں۔"],
["فاسفورس اور کیلشیم کم رکھنے کے لیے ہڈی کے بغیر سالمن تلاش کریں۔ ڈبوں اور فوائل پاؤچز پر سوڈیم کی مقدار کا موازنہ کریں اور کم سوڈیم والا پیک منتخب کریں۔ اس سے بھی بہتر یہ ہے کہ رات کے کھانے کے لیے اضافی تازہ سالمن پکائیں اور بچی ہوئی اس ترکیب کے لیے رکھ لیں۔","یہ ترکیب پہلے سے تیار کی جا سکتی ہے۔ بس ڈھانپ کر پیش کرنے تک فریج میں رکھیں۔","عام مایونیز کی جگہ کم کیلوری والی مایونیز استعمال کی جا سکتی ہے، یا مقدار کم کر کے 1½ کھانے کے چمچ کر لیں (جب تک آپ کو اضافی کیلوری کی ضرورت نہ ہو)۔","ڈبل روٹی کے دیگر انتخاب میں کریکڈ ویٹ، فرنچ، اطالوی، ہلکی رائی، پیٹا یا سوردو شامل ہیں، یا ریپ منتخب کریں۔"],
["2 گوشت","1 چکنائی"]),
(2315,"لیموں کے چوکور ٹکڑے (لیمن اسکوائرز)","لیمن اسکوائرز ایک پسندیدہ میٹھا ہیں۔ اب گردوں کے مریض پوٹاشیم، سوڈیم اور فاسفورس کی مقدار جان کر ان مزیدار ٹکڑوں سے لطف اندوز ہو سکتے ہیں۔","18","2 ٹکڑے",
["1 کپ آئسنگ شوگر (تقسیم کر کے استعمال کریں)","¼ چائے کا چمچ نمک (تقسیم کر کے استعمال کریں)","1 کپ سادہ سفید میدہ","½ کپ بغیر نمک کا مکھن","1 کپ باریک دانے دار چینی","½ چائے کا چمچ بیکنگ پاؤڈر","2 انڈے، ہلکے سے پھینٹے ہوئے","4 کھانے کے چمچ لیموں کا رس (تقسیم کر کے استعمال کریں)","1 کھانے کا چمچ بغیر نمک کا مکھن، نرم کیا ہوا","1 کھانے کا چمچ لیموں کا چھلکا، کدوکش کیا ہوا"],
["بنیاد (کرسٹ) بنانے کے لیے ¼ کپ آئسنگ شوگر، ⅛ چائے کا چمچ نمک، میدہ اور ½ کپ مکھن ملا لیں۔","بغیر چکنائی لگے 8″ چوکور پین میں ڈال کر 350º F پر 15 منٹ بیک کریں۔ اوون سے نکال لیں۔","فلنگ بنانے کے لیے دانے دار چینی، بیکنگ پاؤڈر، ⅛ چائے کا چمچ نمک، پھینٹے ہوئے انڈے، 2 کھانے کے چمچ لیموں کا رس اور کدوکش کیا ہوا لیموں کا چھلکا ملا لیں۔","کرسٹ پر انڈیل کر برابر پھیلا دیں۔","واپس اوون میں رکھ کر 350º F پر مزید 20 منٹ بیک کریں۔ اوون سے نکال کر ٹھنڈا ہونے دیں۔","آئسنگ بنانے کے لیے باقی 2 کھانے کے چمچ لیموں کا رس، ¾ کپ آئسنگ شوگر اور 1 کھانے کا چمچ نرم مکھن ملا لیں۔","جب کرسٹ اور فلنگ کی تہیں مکمل ٹھنڈی ہو جائیں تو اوپر آئسنگ پھیلا دیں۔","فریج میں رکھیں۔ 36 چوکور ٹکڑوں میں کاٹ لیں۔"],
["لیمن اسکوائرز فریز کرنے کے لیے اچھے ہیں۔ انہیں ٹرے میں رکھ کر فریز کریں، پھر فریزر بیگ یا ڈبے میں محفوظ کر لیں۔"],
["½ نشاستہ","1 چکنائی","1 زیادہ کیلوری"]),
(2317,"کرین بیری اور بھنے ہوئے لہسن کا رزوٹو","ڈی واٹا (DaVita) کی غذائی ماہر جینیفر کی کرین بیری اور بھنے ہوئے لہسن کے رزوٹو کی گردوں کے لیے موزوں ترکیب گھر پر خاندان کے ساتھ آرام دہ کھانے کے لیے مثالی ہے، اور مہمانوں کو متاثر کرنے کے لیے کافی خاص بھی۔","4","¾ کپ",
["1 کپ پیاز","2 کھانے کے چمچ مکھن","3 کھانے کے چمچ بھنا ہوا لہسن","¾ کپ آربوریو چاول، کچے","2 کپ کم سوڈیم والا چکن شوربہ","½ کپ میٹھی، خشک کرین بیریز","½ کھانے کا چمچ پارمیزان پنیر"],
["اوون کو 425° F پر پہلے سے گرم کریں۔ کیسرول ڈش پر نان اسٹک کوکنگ اسپرے لگا لیں۔","پیاز باریک کاٹ لیں۔","ایک بڑے ساس پین میں مکھن پگھلا لیں۔ بھنا ہوا لہسن اور پیاز ساس پین میں ڈال کر درمیانی آنچ پر نرم ہونے تک پکائیں۔","چاول ڈال کر 2 منٹ پکائیں۔","چاولوں کے مکسچر میں شوربہ اور خشک کرین بیریز ڈال دیں۔ ابال آنے دیں اور 2 منٹ پکائیں۔","کیسرول ڈش میں انڈیل دیں۔ ڈھانپ کر 30 منٹ بیک کریں۔","اوون سے نکال کر اوپر پارمیزان پنیر چھڑک دیں۔ فوراً پیش کریں۔"],
["بھنا ہوا لہسن ’بھنی ہوئی لہسن کی گانٹھوں‘ کی ترکیب سے تیار کریں یا بوتل میں ملنے والا لہسن اسپریڈ استعمال کریں۔","آربوریو چاول درمیانے دانے کے چاول ہیں جن میں نشاستہ زیادہ ہوتا ہے۔ یہ اٹلی میں اگایا جاتا ہے اور روایتی طور پر رزوٹو کی تراکیب میں استعمال ہوتا ہے۔"],
["2 نشاستہ","1 پھل، کم پوٹاشیم والا","1 چکنائی"]),
(2319,"لذیذ سفید چاول","ٹیکساس کی ڈی واٹا (DaVita) گردوں کی غذائی ماہر کرسٹن اپنی والدہ کی بنائی ہوئی گردوں کے لیے موزوں ترکیب، لذیذ سفید چاول، پیش کرتے ہوئے فخر محسوس کرتی ہیں۔ سفید چاولوں میں نہ صرف ذائقے کی تیزی آ جاتی ہے بلکہ اجوائن، کھمبیوں اور ہری پیاز کی خوشبو اس مزیدار سائیڈ ڈش کے لیے آپ کے منہ میں پانی لے آئے گی۔","8","½ کپ",
["⅓ کپ اجوائن (سیلری)","⅓ کپ ہری پیاز","⅓ کپ کھمبیاں","1 کپ سفید چاول، کچے","2 کپ کم سوڈیم والا چکن شوربہ","1 چائے کا چمچ مارجرین","½ چائے کا چمچ کالی مرچ"],
["اجوائن، ہری پیاز اور کھمبیوں کو پتلا کاٹ لیں۔","چاول ساس پین میں ڈالیں۔ چکن شوربہ ڈال کر درمیانی سے تیز آنچ پر ابال آنے تک گرم کریں۔","اجوائن، ہری پیاز اور کھمبیاں ابلتے ہوئے شوربے میں ڈال دیں۔ سبزیوں کو ہلکا سا شوربے میں دبا دیں۔ آنچ ہلکی کر دیں اور ڈھانپ دیں۔","20 منٹ پکائیں یا جب تک شوربہ خشک نہ ہو جائے اور چاول نرم نہ ہو جائیں۔","مارجرین اور کالی مرچ ڈالیں۔ ملائیں یہاں تک کہ چاولوں پر لگ جائے۔"],
["بچے ہوئے چاول فریج میں رکھیں اور اگلے دن فوری سائیڈ ڈش کے لیے دوبارہ گرم کر لیں۔","اس ڈش کو سائیڈ ڈش سے مین ڈش بنانے کے لیے پکا ہوا کٹا ہوا چکن، ٹوفو یا جھینگے شامل کریں۔"],
["1 نشاستہ","½ سبزی، کم پوٹاشیم والی"]),
(2324,"آسان پیزا ڈو (آٹا)","پیزا ایک کلاسک ڈش ہے اور شاید ہی کوئی ہو جس نے اس کا ایک ٹکڑا نہ چکھا ہو۔ پیزا ڈو کی یہ آسان ترکیب گردوں کی غذا کے لیے بنائی گئی ہے تاکہ گردوں کی بیماری، ذیابیطس یا ڈائیلیسس والے افراد گھر پر بنے مزیدار پیزا سے لطف اندوز ہو سکیں۔","2 پیزا، 16 حصے","پیزا کا 1/8",
["1 کپ پانی","¼ کپ کینولا تیل","3 کپ سادہ میدہ","¼ چائے کا چمچ نمک","1 پیکٹ تیزی سے پھولنے والا خمیر (ریپڈ رائزنگ یسٹ)"],
["اوون کو 450º F پر پہلے سے گرم کریں۔","پانی ناپنے والے کپ میں ڈالیں اور مائیکرو ویو میں 120º سے 130º F تک گرم کریں۔ کینولا تیل ڈال کر ایک طرف رکھ دیں۔","ایک بڑے پیالے میں 2 کپ میدہ، نمک اور خمیر ملا لیں۔ گرم پانی اور تیل ڈال کر ہلائیں تاکہ آٹا بن جائے۔ مزید ½ کپ میدہ ملا دیں۔","آٹے کو میدہ لگے تختے پر رکھیں۔ اوپر میدہ چھڑکیں اور آٹے کو 5 سے 6 منٹ گوندھیں جب تک ہموار اور لچکدار نہ ہو جائے۔ چپکنے سے بچانے کے لیے ضرورت کے مطابق مزید میدہ ڈالیں۔ آدھا آدھا کر کے 2 گولے بنا لیں۔","آٹے کو ڈھانپ کر 10 منٹ پھولنے دیں۔ آٹے کو دبا کر بٹھا دیں اور ہر گولے کو 12″ کے چپٹے پیزا کی شکل دیں۔ پیزا پین یا بیکنگ اسٹون پر رکھ دیں۔","ہر پیزا پر ساس پھیلائیں، پیزا ٹاپنگز ڈالیں اور 425º F پر 12 سے 16 منٹ بیک کریں یہاں تک کہ بلبلے اٹھنے لگیں اور اوپر سے بھورا ہو جائے۔"],
["12″ کا پیزا بنانے کے لیے درمیانے سائز کا پیالہ الٹا کریں اور اس پر میدہ چھڑکیں۔ آٹے کو پیالے کے باہری حصے پر آہستہ آہستہ برابر پھیلائیں؛ پلٹ کر پیزا پین پر رکھ دیں۔","چار انفرادی سائز کے پیزا بنانے کے لیے ہر آٹے کے گولے کو آدھا کر لیں۔","اگر آٹا پھولنے میں مشکل ہو تو اپنے خمیر کی میعاد ختم ہونے کی تاریخ چیک کریں۔ یقینی بنائیں کہ پانی زیادہ گرم نہ ہو کیونکہ اس سے خمیر مر جاتا ہے۔ خمیر کو ’خوراک‘ دینے کے لیے مرحلہ نمبر 3 میں 1 کھانے کا چمچ چینی ڈالیں۔ ترکیب میں تیزی سے کام کرنے والا خمیر استعمال ہوتا ہے۔ عام بیکر کے خمیر سے آٹا پھولنے میں 30 منٹ یا اس سے زیادہ لگ سکتے ہیں۔","بریڈ اسٹکس بنانے کے لیے آٹے کو 16 ٹکڑوں میں تقسیم کریں اور سگار کی شکل کے ٹکڑوں میں بیل لیں۔ 425º F پر سنہری ہونے تک بیک کریں۔","رول بنانے کے لیے آٹے کو 8 رولز میں تقسیم کریں۔ سائز دگنا ہونے تک پھولنے دیں، تیل لگائیں اور 425º F پر سنہری ہونے تک بیک کریں۔","دار چینی کے رولز بنانے کے لیے ہر آٹے کے گولے کو مستطیل شکل میں بیل لیں۔ نرم مکھن لگائیں اور اوپر 1 کھانے کا چمچ دار چینی اور ½ کپ چینی یا دانے دار چینی کا متبادل چھڑکیں۔ لپیٹ لیں اور رول کو 2″ کے ٹکڑوں میں کاٹ لیں۔ دار چینی کے رولز کو مکھن لگی ڈش میں رکھیں اور 400º F پر سنہری ہونے تک بیک کریں۔"],
["1 نشاستہ","½ چکنائی"]),
